const allowed = ["General Medicine", "Dermatology", "Orthopedics", "Cardiology", "ENT", "Pediatrics", "Gynecology"];
const original = String($('Receive Patient Text').first().json.text ?? "");
const lower = original.toLowerCase();
const item = $input.first();
const aiFailed = !!item.json.error;
const raw = aiFailed ? "" : String(item.json.text ?? "");

let data = {};
let parseOk = false;
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");
if (start >= 0 && end > start) {
  try {
    data = JSON.parse(raw.slice(start, end + 1));
    parseOk = true;
  } catch (error) {
    parseOk = false;
  }
}

const keywordRules = [
  { dept: "Pediatrics", rule: /\b(child|children|kid|kids|baby|infant|toddler|newborn|pediatric|paediatric|bachch\w*|bacche|baccha)\b/ },
  { dept: "Gynecology", rule: /\b(pregnan\w*|periods?|menstrua\w*|gynec\w*|gynaec\w*|garbh\w*|pcos)\b/ },
  { dept: "Cardiology", rule: /\b(heart|cardio\w*|blood pressure|palpitation\w*|bp)\b/ },
  { dept: "Dermatology", rule: /\b(skin|rash|acne|pimples?|hair fall|itch\w*|khujli|eczema|dermat\w*)\b/ },
  { dept: "Orthopedics", rule: /\b(knee|knees|ghutn\w*|back pain|joint|joints|bone|bones|fracture|shoulder|kamar|ortho\w*)\b/ },
  { dept: "ENT", rule: /\b(ear|ears|kaan|nose|naak|throat|gala|sinus|tonsil\w*|ent)\b/ },
  { dept: "General Medicine", rule: /\b(check ?up|check-up|fever|bukhar|cough|body ache|general|cold|weakness)\b/ }
];
let keywordDept = "";
for (const entry of keywordRules) {
  if (entry.rule.test(lower)) { keywordDept = entry.dept; break; }
}

let department = String(data.department ?? "").trim();
if (!allowed.includes(department)) { department = "UNCLEAR"; }
let source = "ai";
if (keywordDept && (department === "UNCLEAR" || department === "General Medicine")) {
  if (department !== keywordDept) { source = "keywords"; }
  department = keywordDept;
}

const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Kolkata" });
const addDays = (iso, days) => {
  const d = new Date(iso + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};
const pad = (n) => String(n).padStart(2, "0");

let patientName = String(data.patient_name ?? "").trim();
if (!patientName) {
  const nameMatch = original.match(/(?:my name is|i am|i'm|this is|mera naam|naam)\s+([A-Za-z]+(?: [A-Za-z]+)?)/i);
  if (nameMatch) {
    const words = nameMatch[1].split(" ").filter((w) => !/^(having|need|here|looking|suffering|sick|in|a|an|the|from|and|with|have|has|not|feeling)$/i.test(w));
    patientName = words.join(" ");
  }
}

let date = String(data.date ?? "").trim();
if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(date)) { date = ""; }
if (!date) {
  const iso = original.match(/\b(20[0-9]{2}-[0-9]{2}-[0-9]{2})\b/);
  if (iso) { date = iso[1]; }
  else if (/\b(tomorrow|kal)\b/.test(lower)) { date = addDays(today, 1); }
  else if (/\b(today|aaj)\b/.test(lower)) { date = today; }
  else {
    const days = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    for (let i = 0; i < days.length; i += 1) {
      if (lower.includes(days[i])) {
        const todayNum = new Date(today + "T00:00:00Z").getUTCDay();
        let diff = (i - todayNum + 7) % 7;
        if (diff === 0) { diff = 7; }
        date = addDays(today, diff);
        break;
      }
    }
  }
}

let time = String(data.time ?? "").trim();
if (!/^[0-9]{2}:[0-9]{2}$/.test(time)) { time = ""; }
if (!time) {
  const clock = lower.match(/\b([01]?[0-9]|2[0-3]):([0-5][0-9])\b/);
  const ampm = lower.match(/\b(1[0-2]|0?[1-9])(?::([0-5][0-9]))?\s*(am|pm)\b/);
  if (ampm) {
    let hour = Number(ampm[1]) % 12;
    if (ampm[3] === "pm") { hour += 12; }
    time = pad(hour) + ":" + (ampm[2] || "00");
  } else if (clock) {
    time = pad(Number(clock[1])) + ":" + clock[2];
  }
}

const emergency = data.emergency === true || data.emergency === "true";
const attackWords = /(rules|instructions|prompt|ignore|system|other patients?|database|password)/i;
let refuse = (data.refuse === true || data.refuse === "true") && department === "UNCLEAR" && attackWords.test(original);

const missing = [];
if (department === "UNCLEAR") { missing.push("reason"); }
if (!patientName) { missing.push("name"); }
if (!date) { missing.push("date"); }
if (!time) { missing.push("time"); }
return [{ json: { parse_ok: parseOk || !!keywordDept, department: department, patient_name: patientName, date: date, time: time, emergency: emergency, refuse: refuse, missing: missing.join(","), source: aiFailed ? "keywords (ai unavailable)" : source } }];
